class_name PrevediOrdine
extends RefCounted

func passo_a(registro: Array[String]) -> void:
	registro.append("A")

func passo_b(registro: Array[String]) -> void:
	registro.append("B")

func run() -> String:
	var registro: Array[String] = []
	passo_a(registro)
	passo_b(registro)
	return ",".join(registro)

class_name PrevediAwaitAnnidato
extends RefCounted

signal pronto

func azione_interna() -> int:
	await pronto
	return 40

func operazione() -> int:
	var valore: int = await azione_interna()
	return valore + 2

func run() -> int:
	pronto.emit.call_deferred()
	var totale: int = await operazione()
	return totale
